function validate([strs]) {
  if (!Array.isArray(strs) || strs.length < 1 || strs.length > 100) return 'strs needs 1 to 100 strings.';
  const width = strs[0].length;
  if (width < 1 || width > 100) return 'Each string has 1 to 100 characters.';
  for (const s of strs) {
    if (typeof s !== 'string' || s.length !== width) return 'All strings must have the same length.';
    if (!/^[a-z]+$/.test(s)) return 'Strings may only contain lowercase letters a-z.';
  }
  return null;
}

