function minDeletionSize(strs) {
  const n = strs.length;
  const width = strs[0].length;
  const decided = new Array(n).fill(false);
  let deletions = 0;

  for (let col = 0; col < width; col++) {
    let keep = true;
    for (let i = 0; i + 1 < n; i++) {
      if (!decided[i] && strs[i][col] > strs[i + 1][col]) {
        keep = false;
        break;
      }
    }

    if (!keep) {
      deletions++;
      continue;
    }

    for (let i = 0; i + 1 < n; i++) {
      if (strs[i][col] < strs[i + 1][col]) {
        decided[i] = true;
      }
    }
  }
  return deletions;
}

