function minDeletionSize(strs) {
  const width = strs[0].length;
  const inOrder = (rows) => rows.every((row, i) => i === 0 || rows[i - 1] <= row);
  if (width > 16) {
    // Too many column sets to try: keep a column whenever the actual shortened strings stay in order.
    let rows = strs.map(() => '');
    let deleted = 0;
    for (let j = 0; j < width; j++) {
      const next = rows.map((row, i) => row + strs[i][j]);
      if (inOrder(next)) rows = next;
      else deleted++;
    }
    return deleted;
  }
  // Try every set of kept columns and check whether the shortened strings are in order.
  let best = width;
  for (let mask = 0; mask < (1 << width); mask++) {
    const rows = strs.map(s => [...s].filter((_, j) => mask & (1 << j)).join(''));
    let ordered = true;
    for (let i = 0; i + 1 < rows.length; i++) if (rows[i] > rows[i + 1]) ordered = false;
    if (ordered) {
      let kept = 0;
      for (let j = 0; j < width; j++) if (mask & (1 << j)) kept++;
      best = Math.min(best, width - kept);
    }
  }
  return best;
}

