function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? int(60, 100) : int(1, 5);
  const width = size === 'large' ? int(60, 100) : int(1, 6);
  const alphabet = size === 'large' ? [2, 3, 26][int(0, 2)] : int(1, 3);
  const grid = Array.from({ length: n }, () => Array.from({ length: width }, () => String.fromCharCode(97 + int(0, alphabet - 1))));
  // Usually sort the rows by a random set of columns so that some columns can be kept.
  if (rand() < 0.7) {
    const good = [];
    for (let j = 0; j < width; j++) if (rand() < 0.4) good.push(j);
    grid.sort((a, b) => {
      for (const j of good) if (a[j] !== b[j]) return a[j] < b[j] ? -1 : 1;
      return 0;
    });
  }
  return [grid.map(row => row.join(''))];
}
